    make(5, "若 f(x)＝4x²，則 f(−3) 與 f(3) 的關係為何？", {"A": "f(−3)＝−f(3)", "B": "f(−3)＝f(3)＝12", "C": "f(−3)＝f(3)＝36", "D": "兩者沒有關係"}, "C", "f(−3)＝4(−3)²＝36，f(3)＝4(3)²＝36，因此兩者相等且都是 36，選 C。", "利用相反數平方相同，再計算共同的函數值。", ["寫出 f(−3)＝4(−3)²。", "計算 f(−3)＝4×9＝36。", "寫出 f(3)＝4×3²。", "計算 f(3)＝4×9＝36。", "選 C，得到 f(−3)＝f(3)＝36。"], "easy"),
